// n8n Code (JavaScript) — Run Once for All Items
// Percorre uma lista de CNPJs (vinda em 1 item com array ou vários itens) e retorna o primeiro CNPJ encontrado.

const items = $input.all();

let cnpjs = [];

if (items.length > 0) {
  const firstJson = items[0]?.json;

  if (Array.isArray(firstJson?.cnpjs)) {
    cnpjs = firstJson.cnpjs;
  } else if (Array.isArray(firstJson)) {
    cnpjs = firstJson;
  } else {
    cnpjs = items
      .map(i => i?.json?.cnpj)
      .filter(Boolean);
  }
}

// Normaliza para manter apenas dígitos (14) e filtra vazios
const normalize = (v) => String(v ?? "").replace(/\D/g, "");
const validCnpjs = cnpjs
  .map(raw => ({ raw, digits: normalize(raw) }))
  .filter(x => x.digits.length === 14);

const chosen = (validCnpjs[0]?.raw) ?? (cnpjs[0] ?? null);

if (!chosen) {
  throw new Error("Nenhum CNPJ encontrado nos formatos esperados (ex: `cnpjs: []` ou itens com `cnpj`).");
}

return [
  {
    json: {
      cnpj: chosen,
      cnpj_digits: normalize(chosen),
      found: true,
    },
  },
];
